// The derived Level-3 routines (DESIGN.md §4/P4). Each one is a statement about
// how to reach the GEMM in block.go, not a second implementation of it:
//
//   - Syrk is one gemm call with A on both sides and the C update masked to a
//     triangle.
//   - Symm is one unmasked gemm call whose symmetric operand is reflected as it is
//     packed.
//   - Trsm is a sequence of gemm rank updates against the already-solved part of
//     B, each followed by an unblocked solve against one diagonal block.
//
// This is where the phase's cost/benefit sits. A routine written directly would
// beat the derivation on some shape or other; a routine derived this way inherits
// the packing, the blocking parameters, the beta variants, the edge strategy and —
// the part that took P2 and P3 to establish — the audited K-loop. scripts/gate-p4.sh
// criterion 5 checks the inheritance rather than trusting this comment: every
// derived routine must report the same microkernel and the same kc/mc/nc that
// Sgemm dispatched in the same process.

// triMask confines a C update to one triangle of a square matrix. on false is no
// mask at all, which is how plain Gemm passes through this code unchanged.
//
// The mask is over C's *global* indices, so every predicate takes the position of
// the block or tile in the whole matrix and not its position within its parent
// block. That is the only reason the loop nest in block.go threads ic/jc down to
// macro: a tile cannot tell whether it straddles the diagonal without knowing
// where it is.
type triMask struct {
	on    bool
	lower bool
}

// symOperand names the operand of gemm, if either, that stores only the triangle
// named by lower of a symmetric matrix. The pack reflects it (pack.ASymPanels,
// pack.BSymPanelsPart) instead of the caller expanding it into a dense square
// first; issue #36 is that change and this is the only descriptor it needed.
//
// The zero value is two ordinary operands, which is what every caller but Symm
// passes. It is a property of the source layout and not of who is calling — the
// same thing transA and transB are, and the reason the two flags live side by side
// in gemm's signature.
//
// Never both: A and B are the same matrix only in Syrk, which is masked rather than
// symmetric-sourced. Nothing enforces that, because nothing needs to — a caller
// setting both would get a correct answer, just not one anything asks for.
type symOperand struct {
	a, b, lower bool
}

// keeps reports whether element (i, j) of C is written. Unused by the loop nest,
// which works in ranges rather than element-wise; kept because it is the
// definition the three range predicates below are derived from, and the test
// checks them against it.
func (t triMask) keeps(i, j int) bool {
	if !t.on {
		return true
	}
	if t.lower {
		return i >= j
	}
	return i <= j
}

// whole reports whether every element of the m×n rectangle at (i0, j0) is
// written, i.e. whether the microkernel may write straight into C.
//
// For a lower mask that needs the rectangle's largest column index to be at most
// its smallest row index; for an upper mask, the mirror image. An empty rectangle
// is trivially whole, which keeps the caller from having to special-case it.
func (t triMask) whole(i0, j0, m, n int) bool {
	if !t.on || m <= 0 || n <= 0 {
		return true
	}
	if t.lower {
		return i0 >= j0+n-1
	}
	return i0+m-1 <= j0
}

// none reports whether no element of the m×n rectangle at (i0, j0) is written, so
// the caller can skip packing and the kernel entirely. This is where the roughly
// half of a Syrk that is not computed goes away.
func (t triMask) none(i0, j0, m, n int) bool {
	if m <= 0 || n <= 0 {
		return true
	}
	if !t.on {
		return false
	}
	if t.lower {
		return j0 > i0+m-1
	}
	return i0 > j0+n-1
}

// rowRange returns the half-open range of local column indices written in global
// row gi of a block whose columns start at global j0 and run for n.
//
// The range is contiguous, which is the property that makes the mask cheap: a
// masked row is a shorter row, not a row with a per-element test. lo <= hi always
// holds, so a row entirely outside the triangle comes back empty rather than
// inverted.
func (t triMask) rowRange(gi, j0, n int) (lo, hi int) {
	if !t.on {
		return 0, n
	}
	if t.lower {
		// Columns 0..gi are kept, so the block's window ends at gi+1-j0.
		hi = gi + 1 - j0
		if hi > n {
			hi = n
		}
		if hi < 0 {
			hi = 0
		}
		return 0, hi
	}
	// Columns gi..∞ are kept, so the block's window starts at gi-j0.
	lo = gi - j0
	if lo < 0 {
		lo = 0
	}
	if lo > n {
		lo = n
	}
	return lo, n
}

// Syrk computes C = alpha·A·Aᵀ + beta·C (trans false, A n×k) or
// C = alpha·Aᵀ·A + beta·C (trans true, A k×n), writing only the triangle named by
// lower. It assumes validated arguments; keel.Ssyrk does that.
//
// The whole routine is one GEMM with a itself on both sides and the C update
// masked. Passing the same slice twice is safe because both operands are copied
// into packed panels before the kernel runs and neither is written: the aliasing
// is read-only, which is exactly the case pack.APanels/BPanels do not care about.
//
// The masked half is not computed — see triMask.none — but a tile that straddles
// the diagonal is computed in full and half-discarded, and that waste is what
// gate-p4.sh criterion 7's 85%-of-Sgemm bar measures. It is bounded by the
// diagonal, so it is O(MR·NR/n) of the work.
func Syrk(kn kern.Kernel64, lower, trans bool, n, k int, alpha float64, a []float64, lda int,
	beta float64, c []float64, ldc int) {

	// op(A) is n×k either way, so the second operand is its transpose: A·Aᵀ takes
	// transB true, Aᵀ·A takes transA true and transB false.
	//
	// The ic loop is the parallel axis here exactly as it is for Sgemm, which is
	// the whole reason gate-p5.sh judges the two at the same floor: they are one
	// parallelism class, and this routine is the same nest with a mask. The mask
	// is what makes the blocks unequal, and icOrder is where that is dealt with.
	beginCall()
	gemm(kn, trans, !trans, n, n, k, alpha, a, lda, a, lda, beta, c, ldc,
		triMask{on: true, lower: lower}, symOperand{}, splitIC)
}

// Symm computes C = alpha·A·B + beta·C (left) or C = alpha·B·A + beta·C (right)
// for A symmetric and stored in the triangle named by lower. A is m×m in the left
// case and n×n in the right one. It assumes validated arguments; keel.Ssymm does
// that.
//
// # Why the pack reflects A rather than this expanding it
//
// The panel at (ic, pc) needs A's entries on both sides of the diagonal, and the
// ones past it live at their reflections. Until issue #36 this reflected A once into
// a dense d×d square and handed gemm an ordinary matrix, which cost O(d²) of scratch
// — 67 MB at d=4096, measured at 16,904,645 B/op at d=2048 — plus a whole d² pass
// over A before the pack made its own. Asymptotically free against the multiply's
// O(d²·n); not free in allocator and memory traffic, which is what it was.
//
// What it was NOT is a serial region. `expandSym` ran under par.Run over A's rows
// from 175098d onward, so deleting it removed no Amdahl term, and an earlier draft of
// this comment claiming otherwise was wrong. See the #36 thread.
//
// Now the reflection happens inside the pack, where it costs neither scratch nor a
// pass: see internal/pack.ASymPanels. The alternative — a symmetric microkernel — is
// still not on the table, because it would double the kernel family P2 audited.
//
// The values are the same either way, bit for bit: reflecting during the pack reads
// the same stored element the dense square would have held, and the alpha it is then
// scaled by is the same one. TestSymPackMatchesExpansion in internal/pack pins that
// against a literal expansion.
//
// alpha == 0 returns beta·C without reading A, matching reference SSYMM. A's
// unreferenced triangle may hold anything, so a routine that read it in order to
// multiply it by zero would produce NaN on a legal call.
func Symm(kn kern.Kernel64, left, lower bool, m, n int, alpha float64, a []float64, lda int,
	b []float64, ldb int, beta float64, c []float64, ldc int) {

	if m == 0 || n == 0 {
		return
	}
	beginCall()
	if alpha == 0 {
		scaleTri(beta, 0, 0, m, n, c, ldc, triMask{})
		return
	}
	sym := symOperand{lower: lower}
	if left {
		sym.a = true
		gemm(kn, false, false, m, n, m, alpha, a, lda, b, ldb, beta, c, ldc, triMask{}, sym, splitIC)
		return
	}
	sym.b = true
	gemm(kn, false, false, m, n, n, alpha, b, ldb, a, lda, beta, c, ldc, triMask{}, sym, splitIC)
}

// MB is the row (left) or column (right) block size of Trsm's outer loop: how
// much of B is solved against one diagonal block of A before the next rank update.
// A var for the same reason KC/MC/NC are — it trades the unblocked solve's scalar
// work against the rank update's blocked work, and that balance is a measurement.
//
// MEASURED 2026-10-11 (#37) AND DELIBERATELY NOT CHANGED. The sweep — 7 values x
// 2 sides x n in {2048, 4096}, pass-major with the MB order reshuffled every pass
// and per-pass load recorded — found NO value better than 64 in all four cells,
// so the pre-registered rule left the global alone. The per-cell optima, median
// vs 64, pass-2 excluded as contaminated:
//
//	n=2048 side=L: MB=96  -2.6%      n=2048 side=R: MB=48  -14.7%
//	n=4096 side=L: MB=256 -5.6%      n=4096 side=R: MB=48   -6.5%
//
// (These are from before #181 changed solveRight, so the side=R column is stale.
// Re-swept at n=2048 only after #186 sped up the pack of X, one thread, dev tier,
// medians of 3 on a loaded host: on 3x24, side=R is -5.8% at 48, -10.3% at 72 and
// -10.4% at 96 against 64, side=L flat within 1% from 48 to 96. Every winner is a
// multiple of NR=24 and 64 is not — the side=R rank update's N is the block, so it
// pads to 72 — which makes the right side's optimum a property of NR, not of
// Trsm. 4x16 and 8x8 show no side=R win over 64. Not a dominance result either:
// n=4096 was not re-run, and side=L's -0.9% at 72 is inside the run's spread.)
// THE TWO SIDES PULL IN OPPOSITE DIRECTIONS and that is the finding, not the
// winner: side=R wants 48 at both n while side=L pays +6.8% there and wants 96
// then 256. MB=48 is the best single compromise (mean -3.7%, better in 3 of 4
// cells) and still fails the dominance test, which is why it did not land. A
// correct fix is a per-side block size — trsmLeft and trsmRight are already
// separate functions — but the values for it need the judged fleet, since this is
// one 4-lane NEON core and MB is shared by every backend.
var MB = 64

// Axpy is the unit-stride y += alpha*x that the diagonal solves need, threaded in
// rather than reached for. This follows kern.Kernel exactly: the root dispatcher
// owns backend selection (dispatch.go holds activeL1 beside activeKern), so
// internal/block needs neither a mutable global nor an internal/l1 import, and a
// test can hand in whichever backend it means to exercise.
//
// It must NOT short-circuit alpha == 0 — see Trsm's doc comment on 0*Inf — and no
// l1 backend does. A nil Axpy is a wiring bug and panics rather than falling back
// to the scalar loop: a silent fallback would let a benchmark measure the scalar
// path while its name claimed the vector one (#37).
type Axpy func(alpha float64, x, y []float64)

// ScalDiv is the unit-stride x /= alpha the diagonal solves need for the
// division by the diagonal element. Threaded in beside Axpy, and separate from
// it because the two ops are separate in l1 for a numerics reason: this one must
// DIVIDE, not scale by a reciprocal (see Trsm's doc comment, and
// l1.TestScalDivIsNotAReciprocalMultiply, which drives that distinction on a
// witness it re-derives each run).
type ScalDiv func(alpha float64, x []float64)

// Trsm solves op(A)·X = alpha·B (left) or X·op(A) = alpha·B (right) for X,
// overwriting B, where A is triangular and stored in the triangle named by lower.
// A is m×m in the left case and n×n in the right one. unit means A's stored
// diagonal is not referenced and is taken to be 1. It assumes validated
// arguments; keel.Strsm does that.
//
// # The recipe
//
// This is the blocked algorithm from BLIS (Van Zee & van de Geijn, "BLIS: A
// Framework for Rapidly Instantiating BLAS Functionality", TOMS 2015, §4.3; the
// same partitioning appears in Goto & van de Geijn's TOMS 2008 §4 as the trsm
// variant of the GEMM nest). Partition B into MB-row blocks in solve order. Each
// block's own equations involve only one diagonal block of A plus the blocks
// already solved, so:
//
//	B_i := alpha·B_i - op(A)[i, solved]·X[solved]     one gemm, k = solved rows
//	solve op(A)_ii · X_i = B_i                        unblocked, MB×MB triangle
//
// The first block has nothing solved yet, so its update degenerates to B_i·=alpha
// — which is what gemm's k == 0 path already does, so it is not special-cased
// here. All of the flops except the diagonal blocks' O(m·MB·n) go through the
// audited kernel.
//
// "The unblocked solves are scalar, and at MB = 64 they are a few percent of the
// work" is what this said until 2026-10-11, estimated from the loop structure and
// never measured. BOTH HALVES WERE WRONG. solveLeft is no longer scalar (#37: its
// length-n axpy and its divide both vectorized), and the solves were never a few
// percent of the TIME: at MB = 64 they are 12.0% of Trsm on the left and 53.2% on
// the right at n=2048 (7.2% / 38.4% at n=4096), against ~3% of the flops. The
// confusion was work for time, which is the whole reason #37 asked for a
// measurement first.
//
// solveRight USED TO cost 7.5-7.7x solveLeft at identical flop counts, because its
// vectorizable axis was the short one. Since #181 it is solveLeft on a transposed
// copy of the column window, and the solve-only gap is ~1.2x on the M4 Pro dev host
// (21 ms against 18 ms; was 171) and ~2.2x on janus's AVX-512 (23 ms against 10;
// was 251), n=2048, MB=64, one thread, unjudged. The side=R MB optimum at MB's
// declaration was measured on the old form; the re-sweep is beside it.
//
// The rank update was then the right side's gap (#186): X is that gemm's A operand,
// so it takes the transposing A pack, against the left side's memmove of X as B.
// Split with BenchmarkTrsmMB's rank-pack arms on the M4 Pro's shipped 3x24 (n=2048,
// MB=64, one thread, dev tier): packing X took 30.6 ms of side=R's ~173 ms rank
// update against 14.1 ms of side=L's ~136, and pack.depthPanel cut it to 18.6.
// Rank update ≈ full − solve-only, R/L, after: 1.20x on 3x24, 1.04x on 4x16, 0.95x
// on 8x8 (was 1.29x, 1.13x, 1.10x). Part of what 3x24 keeps is kernel padding: the
// side=R gemm's N is the 64-column block, which pads to 72 at NR=24, against
// side=L's 64 rows padding to 66 at MR=3: rank-no-pack is 132.4 ms against 125.3.
//
// janus (2x32 AVX-512, build queue, indicative) is a different story. side=R full
// went 269 → 243 ms, the X pack alone 156 → 57, but X's pack IN SITU (full −
// solve-only − rank-no-pack) only 135 → 114, against side=L's ~30. The kernels
// return with dirty upper ZMM state and the scalar pack is legacy-SSE code, so it
// runs 2.2x slower right after a kernel call than alone (BenchmarkPackAfterKernel).
// 57 ms at 2.2x predicts ~125 in situ, against the 114 measured — a prediction from
// a microbenchmark, not an in-situ A/B. The candidate fix is a VZEROUPPER at the
// kernel boundary, which is internal/vec's to make and has not been tried.
//
// What these solves must not do is get clever: they divide rather than multiply by a
// reciprocal (a reciprocal changes the answer in the last bit and disagrees with
// the oracle for no gain), and they do not skip a zero multiplier (BLAS requires
// 0·Inf to propagate NaN, and a "fast path" for a zero in A would silently return
// a different matrix on an input that is legal and, in a factored matrix, common).
//
// alpha == 0 sets B to zero and returns without reading A at all, matching
// reference STRSM. A is otherwise required to be nonsingular in its referenced
// triangle; keel does not check that, and neither does reference BLAS.
func Trsm(kn kern.Kernel64, ax Axpy, sd ScalDiv, left, lower, trans, unit bool, m, n int, alpha float64,
	a []float64, lda int, b []float64, ldb int) {

	if ax == nil || sd == nil {
		panic("block.Trsm: nil Axpy or ScalDiv (a registration bug, not a fallback)")
	}
	if m == 0 || n == 0 {
		return
	}
	beginCall()
	if alpha == 0 {
		for i := 0; i < m; i++ {
			clear(b[i*ldb : i*ldb+n])
		}
		return
	}
	// op(A) is lower triangular when exactly one of lower and trans holds, since
	// transposing a lower triangle gives an upper one. Everything below keys off
	// that one derived fact rather than off the two flags separately — the same
	// reduction the oracle makes, arrived at independently there.
	lowerEff := lower != trans
	if left {
		strips(n, func(j0, jn int) {
			trsmLeft(kn, ax, sd, lowerEff, trans, unit, m, jn, alpha, a, lda, b[j0:], ldb)
		})
		return
	}
	strips(m, func(i0, im int) {
		trsmRight(kn, ax, sd, lowerEff, trans, unit, im, n, alpha, a, lda, b[i0*ldb:], ldb)
	})
}

// strips splits axis into par.Workers(axis) contiguous non-empty ranges and runs
// fn on one range per worker.
//
// # Why Trsm parallelizes here and not in the nest it calls
//
// This is the second parallelism class scripts/gate-p5.sh names (criterion 1),
// and the reason it is a second class is visible in the shape of its rank update.
// trsmLeft solves MB rows of B at a time, so its gemm is MB×n×k with MB = 64 —
// fewer rows than one MC block. The ic loop the other three routines parallelize
// has exactly one iteration there, so splitting it would yield one worker no
// matter what GOMAXPROCS says.
//
// What Trsm has instead is the axis its block loop cannot use: the right-hand
// sides. Column j of X depends on column j of B and on nothing else, so for the
// left-side solve the whole routine — rank updates, diagonal solves and all —
// partitions over columns of B with no interaction whatsoever. The right-side
// solve is the mirror image over rows. That is a better partition than the ic loop
// would have been even if the shape allowed it: each worker touches a disjoint
// slice of B rather than sharing one.
//
// So the split happens once, at the top, and the rank updates inside run
// noSplit — see the split type. Nesting the two would multiply GOMAXPROCS by
// itself and make "bounded pool" a description of nothing.
//
// The ranges are cut as u·axis/w rather than by a fixed width, which is what
// guarantees every one of them is non-empty when w ≤ axis: a ceil-width partition
// of 10 units into 8 leaves three workers with nothing, and a worker with nothing
// is a workers=5 declaration on a threads=8 row.
func strips(axis int, fn func(off, count int)) {
	w := par.Workers(axis)
	if w < 1 {
		return
	}
	recordWorkers(par.Run(w, func(claim func() int) {
		for u := claim(); u >= 0; u = claim() {
			lo, hi := u*axis/w, (u+1)*axis/w
			fn(lo, hi-lo)
		}
	}))
}

// TrsmWork reports how the useful flops of a Trsm at this shape divide between
// the blocked rank updates, which go through the audited microkernel, and the
// unblocked diagonal solves, which do not.
//
// The two are absolute counts rather than fractions, so that a caller can check
// their sum against the total it believes the shape has before dividing by it. A
// pair of fractions summing to 1 is self-consistent no matter how wrong both are.
//
// This is the parallelism model gate-p5.sh criterion 1 requires beside Strsm's
// measured scaling, and requiring it is the point: Strsm's floor is deferred to a
// measurement PLUS a model, because a scaling number with no account of what
// fraction of the work can scale sets no threshold anybody can defend. The
// diagonal solves are the part with the serial dependency; the rank updates are
// the part that behaves like the class above.
//
// It walks the same MB partition Trsm walks rather than evaluating a closed form,
// so a change to MB or to the blocking moves this with it. The count is of USEFUL
// flops on the same convention as scripts/gate-p5.sh's flops_expect — one
// multiply-add per (row, column) pair of one triangle including its diagonal, per
// right-hand side — so the two must sum to n·m·(m+1) for a left-side solve, and
// p5_test.go asserts exactly that rather than leaving the two counts to agree by
// eye.
//
// Direction does not enter it. The rank-update term is 2·rhs·Σ_{i<j} mb_i·mb_j
// over the block partition, which is symmetric in the block order, so a forward
// solve over a lower triangle and a backward solve over an upper one have the
// same decomposition.
func TrsmWork(left bool, m, n int) (rankUpdate, diagSolve float64) {
	// The blocked axis and the number of right-hand sides swap with the side: a
	// left solve blocks over m and carries n columns, a right solve blocks over n
	// and carries m rows.
	axis, rhs := m, n
	if !left {
		axis, rhs = n, m
	}
	var solved int
	for off := 0; off < axis; off += MB {
		bl := min(MB, axis-off)
		rankUpdate += 2 * float64(bl) * float64(rhs) * float64(solved)
		diagSolve += float64(rhs) * float64(bl) * float64(bl+1)
		solved += bl
	}
	return rankUpdate, diagSolve
}

// trsmLeft solves op(A)·X = alpha·B, forward over row blocks when op(A) is lower
// triangular and backward when it is upper.
func trsmLeft(kn kern.Kernel64, ax Axpy, sd ScalDiv, lowerEff, trans, unit bool, m, n int, alpha float64,
	a []float64, lda int, b []float64, ldb int) {

	nb := (m + MB - 1) / MB
	for step := 0; step < nb; step++ {
		bi := step
		if !lowerEff {
			bi = nb - 1 - step
		}
		i0 := bi * MB
		mb := min(MB, m-i0)
		// The rows of X already solved: everything above this block when op(A) is
		// lower, everything below it when op(A) is upper.
		p0, kk := 0, i0
		if !lowerEff {
			p0, kk = i0+mb, m-(i0+mb)
		}
		if kk == 0 {
			// Nothing solved yet, so the update is just the scaling. Not routed
			// through gemm's k == 0 path because p0 can be m here, and indexing a
			// zero-length operand at the end of the matrix is out of range.
			scaleTri(alpha, 0, 0, mb, n, b[i0*ldb:], ldb, triMask{})
		} else {
			// op(A)[i0+r, p0+p] is a[p0+p][i0+r] transposed and a[i0+r][p0+p] not,
			// so the operand's origin moves but its shape is always mb×kk with the
			// transpose flag doing the work.
			asl := a[i0*lda+p0:]
			if trans {
				asl = a[p0*lda+i0:]
			}
			// noSplit: this whole solve is already one worker's strip of B (see
			// strips), and the rank update's mb rows are fewer than one MC block
			// anyway, so the ic loop has nothing to hand out.
			gemm(kn, trans, false, mb, n, kk, -1, asl, lda, b[p0*ldb:], ldb,
				alpha, b[i0*ldb:], ldb, triMask{}, symOperand{}, noSplit)
		}
		solveLeft(ax, sd, lowerEff, trans, unit, mb, n, a[i0*lda+i0:], lda, b[i0*ldb:], ldb)
	}
}

// trsmRight solves X·op(A) = alpha·B. The direction is the mirror of the left
// case: column block j of X depends on the blocks before it when op(A) is upper
// and on the blocks after it when op(A) is lower.
func trsmRight(kn kern.Kernel64, ax Axpy, sd ScalDiv, lowerEff, trans, unit bool, m, n int, alpha float64,
	a []float64, lda int, b []float64, ldb int) {

	nblk := (n + MB - 1) / MB
	t := make([]float64, tStride(m)*min(MB, n)) // solveRight's transpose of one column window
	for step := 0; step < nblk; step++ {
		bj := step
		if lowerEff {
			bj = nblk - 1 - step
		}
		j0 := bj * MB
		nb := min(MB, n-j0)
		p0, kk := 0, j0
		if lowerEff {
			p0, kk = j0+nb, n-(j0+nb)
		}
		if kk == 0 {
			scaleTri(alpha, 0, 0, m, nb, b[j0:], ldb, triMask{})
		} else {
			// The X operand is a column window of B, so its row stride is ldb; the
			// A operand is op(A)[p0.., j0..], kk×nb.
			bsl := a[p0*lda+j0:]
			if trans {
				bsl = a[j0*lda+p0:]
			}
			// noSplit, for the reason trsmLeft's rank update gives.
			gemm(kn, false, trans, m, nb, kk, -1, b[p0:], ldb, bsl, lda,
				alpha, b[j0:], ldb, triMask{}, symOperand{}, noSplit)
		}
		solveRight(ax, sd, lowerEff, trans, unit, m, nb, a[j0*lda+j0:], lda, b[j0:], ldb, t)
	}
}

// solveLeft solves op(A)·X = B in place for one d×d diagonal block, over all n
// columns of B at once. a points at the diagonal block's first element.
//
// The row-at-a-time shape is deliberate: B's rows are contiguous, so the inner
// loop is a unit-stride axpy over n and the substitution's serial dependency is
// paid once per row of the block rather than once per element.
func solveLeft(ax Axpy, sd ScalDiv, lowerEff, trans, unit bool, d, n int, a []float64, lda int, b []float64, ldb int) {
	for step := 0; step < d; step++ {
		i := step
		if !lowerEff {
			i = d - 1 - step
		}
		row := b[i*ldb : i*ldb+n]
		plo, phi := 0, i
		if !lowerEff {
			plo, phi = i+1, d
		}
		for p := plo; p < phi; p++ {
			aip := a[i*lda+p]
			if trans {
				aip = a[p*lda+i]
			}
			// THE SUBSTITUTION (#37). This loop is length n, not length d: it
			// runs the full width of B for every (i, p) pair in the diagonal
			// block, so it is the routine's long unit-stride inner loop and Go
			// does not vectorize it. Measured share of Trsm's time before this
			// change, on the shipped NEON kernel at n=2048/MB=64: 22.2% of the
			// left side and 49.3% of the right, against 1.587% of the flops.
			//
			// NOT bit-identical to the scalar loop it replaces, and that is
			// permitted here where it would not be in solveRight: a vector axpy
			// reassociates nothing but may fuse the multiply-subtract, which
			// l1's documented contract already covers (results are held to
			// oracle.Tolerance, not to bit-equality). solveRight's interchange
			// claimed bit-identity because it was a pure reordering; this is a
			// different kernel and claims only the tolerance.
			ax(-aip, b[p*ldb:p*ldb+n], row)
		}
		if !unit {
			// Divide, do not scale by a reciprocal: see Trsm's doc comment. The
			// diagonal is a[i][i] whether or not op transposes.
			//
			// VECTORIZED (#37, 2026-10-11) and this one IS bit-identical to the
			// scalar loop it replaces, unlike the axpy above: VDIVPS and VFDIV
			// are per-lane IEEE divides, so there is nothing to reassociate and
			// nothing to fuse. l1's ScalDiv is held to plain Go division with no
			// tolerance for exactly that reason, which is why vectorizing a
			// divide does not re-open the reciprocal question this comment has
			// guarded since P4.
			sd(a[i*lda+i], row)
		}
	}
}

// solveRight solves X·op(A) = B in place for one d×d diagonal block, over all m
// rows of B. a points at the diagonal block's first element, b at its column
// window of B, and t is scratch of at least d·m elements.
//
// # It is the left solve on the transpose (#181)
//
// X·op(A) = B is op(A)ᵀ·Xᵀ = Bᵀ, so the block's window of B is transposed into t
// (d rows of length m), solveLeft runs on it with op(A)ᵀ — trans and the effective
// triangle both flip, the diagonal is the same — and the result is transposed back.
// The point is the inner loop. In X·op(A) = B the dependency runs along a row of
// length d ≤ MB, so the only loop available there is a short reduction, strided by
// lda when op(A) is not transposed. On the transpose the dependency runs down t's
// rows and the inner loop is solveLeft's unit-stride axpy over m, the same vector
// code the left side already uses. The two copies are O(m·d) against the solve's
// O(m·d²).
//
// The previous form, a row-outermost substitution (#37), is kept in tri_test.go as
// solveRightRows, with the strided original it was bit-identical to. This form is
// not bit-identical to either: the axpy may fuse its multiply-subtract and runs the
// p order per row of t rather than per element, so it is held to oracle.Tolerance,
// as solveLeft is. It still divides rather than multiplying by a reciprocal, and
// skips no zero multiplier, because solveLeft does neither.
// tStride is the row stride of solveRight's transpose buffer: m, padded by one
// 64-byte line (16 float32s) so that the d rows it writes per row of B do not map
// to the same cache sets when m is a power of two. In bytes, so the generated
// float64 copy pads by the same line.
func tStride(m int) int { return m + int(64/unsafe.Sizeof(float64(0))) }

func solveRight(ax Axpy, sd ScalDiv, lowerEff, trans, unit bool, m, d int, a []float64, lda int, b []float64, ldb int, t []float64) {
	ldt := tStride(m)
	t = t[:d*ldt]
	for i := 0; i < m; i++ {
		for j, v := range b[i*ldb : i*ldb+d] {
			t[j*ldt+i] = v
		}
	}
	solveLeft(ax, sd, !lowerEff, !trans, unit, d, m, a, lda, t, ldt)
	for i := 0; i < m; i++ {
		row := b[i*ldb : i*ldb+d]
		for j := range row {
			row[j] = t[j*ldt+i]
		}
	}
}
